<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login(); $pdo=db();
if(!table_exists($pdo,'document_requirements')) redirect('upgrade_phase4.php');
$msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(post_string('action')==='add'){$name=post_string('name');$service=post_int('service_id')?:null;if($name){$st=$pdo->prepare('INSERT INTO document_requirements(service_id,name,description,allowed_mimes,max_size_mb,is_required) VALUES(?,?,?,?,?,?)');$st->execute([$service,$name,post_string('description')?:null,post_string('allowed_mimes')?:'application/pdf,image/jpeg,image/png',max(1,post_int('max_size_mb',10)),isset($_POST['is_required'])?1:0]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','document_requirements',$id,'Document requirement created');flash('success','Document requirement created.');}redirect('document_requirements.php');}}
$services=$pdo->query("SELECT id,name FROM services WHERE status='active' ORDER BY name")->fetchAll();
$rows=$pdo->query("SELECT dr.*,s.name service_name FROM document_requirements dr LEFT JOIN services s ON s.id=dr.service_id ORDER BY dr.id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Document Requirements · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:11px 14px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Document Requirements</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="grid"><div class="card"><h2>New Requirement</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="field"><label>Service</label><select name="service_id"><option value="">All / general</option><?php foreach($services as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Allowed MIME types</label><input name="allowed_mimes" value="application/pdf,image/jpeg,image/png"></div><div class="field"><label>Max size (MB)</label><input name="max_size_mb" type="number" min="1" value="10"></div><label><input type="checkbox" name="is_required" checked> Required</label><br><br><button class="btn">Create Requirement</button></form></div><div class="card"><h2>Requirements</h2><table class="table"><tr><th>Requirement</th><th>Service</th><th>Required</th><th>Types</th><th>Size</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['service_name']?:'General')?></td><td><?=($r['is_required']?'Yes':'No')?></td><td><?=e($r['allowed_mimes'])?></td><td><?=e($r['max_size_mb'])?> MB</td></tr><?php endforeach;?></table></div></div></main></body></html>
